-- TEST 1: MBTI (60 bipolar questions, 16 personality types)
-- ============================================================
INSERT INTO public.tests (slug, title, description, category, estimated_minutes, questions, scoring, result_types)
VALUES (
  'mbti',
  'Тест MBTI — Тип личности',
  'Методика Майерс-Бриггс определяет тип личности по 4 шкалам: Экстраверсия/Интроверсия, Сенсорика/Интуиция, Логика/Этика, Рациональность/Иррациональность.',
  'personality',
  25,
  '[
    {"id":1,"text":"На вечеринке вы обычно:","dimension":"EI","type":"bipolar","options":[{"text":"Легко знакомитесь и болтаете с разными людьми","value":"E"},{"text":"Общаетесь с теми, кого уже знаете","value":"I"}]},
    {"id":2,"text":"Вы чувствуете себя более энергичным после:","dimension":"EI","type":"bipolar","options":[{"text":"Общения с друзьями","value":"E"},{"text":"Времени наедине с собой","value":"I"}]},
    {"id":3,"text":"В незнакомой компании вы:","dimension":"EI","type":"bipolar","options":[{"text":"Быстро вступаете в разговор","value":"E"},{"text":"Предпочитаете сначала присмотреться","value":"I"}]},
    {"id":4,"text":"Вам проще:","dimension":"EI","type":"bipolar","options":[{"text":"Говорить, чем слушать","value":"E"},{"text":"Слушать, чем говорить","value":"I"}]},
    {"id":5,"text":"Вы скорее:","dimension":"EI","type":"bipolar","options":[{"text":"Открытый и общительный человек","value":"E"},{"text":"Замкнутый и сдержанный человек","value":"I"}]},
    {"id":6,"text":"В выходные вы предпочитаете:","dimension":"EI","type":"bipolar","options":[{"text":"Встречаться с большим количеством людей","value":"E"},{"text":"Побыть дома или с близкими","value":"I"}]},
    {"id":7,"text":"Вам легче думается когда:","dimension":"EI","type":"bipolar","options":[{"text":"Вы вслух проговариваете мысли","value":"E"},{"text":"Вы спокойно обдумываете всё внутри","value":"I"}]},
    {"id":8,"text":"Новые знакомства для вас:","dimension":"EI","type":"bipolar","options":[{"text":"Приятны и интересны","value":"E"},{"text":"Немного утомительны","value":"I"}]},
    {"id":9,"text":"В споре вы:","dimension":"EI","type":"bipolar","options":[{"text":"Охотно высказываете своё мнение","value":"E"},{"text":"Предпочитаете промолчать лишний раз","value":"I"}]},
    {"id":10,"text":"Чтобы восстановить силы, вам нужно:","dimension":"EI","type":"bipolar","options":[{"text":"Сходить куда-нибудь с людьми","value":"E"},{"text":"Отдохнуть в тишине","value":"I"}]},
    {"id":11,"text":"Ваш круг знакомых:","dimension":"EI","type":"bipolar","options":[{"text":"Широкий — много разных людей","value":"E"},{"text":"Узкий — несколько близких друзей","value":"I"}]},
    {"id":12,"text":"Вы предпочитаете работать:","dimension":"EI","type":"bipolar","options":[{"text":"В команде с другими людьми","value":"E"},{"text":"Самостоятельно","value":"I"}]},
    {"id":13,"text":"После долгого общения вы чувствуете:","dimension":"EI","type":"bipolar","options":[{"text":"Подъём и радость","value":"E"},{"text":"Усталость, нужно побыть одному","value":"I"}]},
    {"id":14,"text":"Когда нужно принять решение, вы:","dimension":"EI","type":"bipolar","options":[{"text":"Советуетесь с окружающими","value":"E"},{"text":"Всё обдумываете самостоятельно","value":"I"}]},
    {"id":15,"text":"Вас можно назвать:","dimension":"EI","type":"bipolar","options":[{"text":"Душой компании","value":"E"},{"text":"Человеком-загадкой","value":"I"}]},
    {"id":16,"text":"Вы больше доверяете:","dimension":"SN","type":"bipolar","options":[{"text":"Проверенным фактам и конкретному опыту","value":"S"},{"text":"Интуиции и внутренним ощущениям","value":"N"}]},
    {"id":17,"text":"Вас больше интересует:","dimension":"SN","type":"bipolar","options":[{"text":"То, что происходит сейчас","value":"S"},{"text":"То, что может произойти в будущем","value":"N"}]},
    {"id":18,"text":"Вы предпочитаете инструкции:","dimension":"SN","type":"bipolar","options":[{"text":"Подробные и пошаговые","value":"S"},{"text":"Дающие общее направление","value":"N"}]},
    {"id":19,"text":"В разговоре вы:","dimension":"SN","type":"bipolar","options":[{"text":"Придерживаетесь фактов","value":"S"},{"text":"Охотно используете метафоры и образы","value":"N"}]},
    {"id":20,"text":"Вы скорее:","dimension":"SN","type":"bipolar","options":[{"text":"Практичны и реалистичны","value":"S"},{"text":"Изобретательны и мечтательны","value":"N"}]},
    {"id":21,"text":"Вам важнее:","dimension":"SN","type":"bipolar","options":[{"text":"Что-то конкретное и ощутимое","value":"S"},{"text":"Идеи и концепции","value":"N"}]},
    {"id":22,"text":"Вас привлекает работа, которая:","dimension":"SN","type":"bipolar","options":[{"text":"Ясна и предсказуема","value":"S"},{"text":"Требует творчества и поиска нового","value":"N"}]},
    {"id":23,"text":"При изучении нового вы предпочитаете:","dimension":"SN","type":"bipolar","options":[{"text":"Начинать с деталей, а потом видеть картину целиком","value":"S"},{"text":"Сначала понять общую идею, потом детали","value":"N"}]},
    {"id":24,"text":"В книге вас больше привлекает:","dimension":"SN","type":"bipolar","options":[{"text":"Точное описание происходящего","value":"S"},{"text":"Авторская фантазия и символика","value":"N"}]},
    {"id":25,"text":"Вы склонны:","dimension":"SN","type":"bipolar","options":[{"text":"Жить настоящим","value":"S"},{"text":"Думать о будущем","value":"N"}]},
    {"id":26,"text":"Ваша сильная сторона:","dimension":"SN","type":"bipolar","options":[{"text":"Здравый смысл","value":"S"},{"text":"Воображение","value":"N"}]},
    {"id":27,"text":"Вы чаще думаете о:","dimension":"SN","type":"bipolar","options":[{"text":"Том, что реально и осязаемо","value":"S"},{"text":"Возможностях и вариантах развития событий","value":"N"}]},
    {"id":28,"text":"В работе вы цените:","dimension":"SN","type":"bipolar","options":[{"text":"Проверенные методы","value":"S"},{"text":"Новые подходы и эксперименты","value":"N"}]},
    {"id":29,"text":"Вас описывают как человека:","dimension":"SN","type":"bipolar","options":[{"text":"Приземлённого и конкретного","value":"S"},{"text":"С головой в облаках","value":"N"}]},
    {"id":30,"text":"В планировании вы:","dimension":"SN","type":"bipolar","options":[{"text":"Ориентируетесь на детали и конкретные шаги","value":"S"},{"text":"Видите общую картину и возможности","value":"N"}]},
    {"id":31,"text":"Принимая решения, вы прежде всего:","dimension":"TF","type":"bipolar","options":[{"text":"Опираетесь на логику и анализ","value":"T"},{"text":"Учитываете чувства и ценности людей","value":"F"}]},
    {"id":32,"text":"Для вас важнее быть:","dimension":"TF","type":"bipolar","options":[{"text":"Справедливым","value":"T"},{"text":"Милосердным","value":"F"}]},
    {"id":33,"text":"Вас больше задевает:","dimension":"TF","type":"bipolar","options":[{"text":"Несправедливость","value":"T"},{"text":"Бессердечность","value":"F"}]},
    {"id":34,"text":"В споре вы:","dimension":"TF","type":"bipolar","options":[{"text":"Стараетесь доказать свою правоту","value":"T"},{"text":"Стремитесь к согласию и миру","value":"F"}]},
    {"id":35,"text":"При критике другого человека вы:","dimension":"TF","type":"bipolar","options":[{"text":"Говорите прямо, даже если это больно","value":"T"},{"text":"Смягчаете слова, чтобы не обидеть","value":"F"}]},
    {"id":36,"text":"Вам проще:","dimension":"TF","type":"bipolar","options":[{"text":"Критиковать плохую работу","value":"T"},{"text":"Хвалить хорошую работу","value":"F"}]},
    {"id":37,"text":"Вы считаете себя:","dimension":"TF","type":"bipolar","options":[{"text":"Хладнокровным и рациональным","value":"T"},{"text":"Тёплым и сочувствующим","value":"F"}]},
    {"id":38,"text":"При принятии сложного решения вас волнует:","dimension":"TF","type":"bipolar","options":[{"text":"Что является правильным с точки зрения логики","value":"T"},{"text":"Как это решение повлияет на людей","value":"F"}]},
    {"id":39,"text":"Вы скорее:","dimension":"TF","type":"bipolar","options":[{"text":"Скептик","value":"T"},{"text":"Идеалист","value":"F"}]},
    {"id":40,"text":"Вас описывают как:","dimension":"TF","type":"bipolar","options":[{"text":"Аналитичного","value":"T"},{"text":"Чуткого","value":"F"}]},
    {"id":41,"text":"Когда друг рассказывает о проблеме, вы:","dimension":"TF","type":"bipolar","options":[{"text":"Предлагаете конкретные решения","value":"T"},{"text":"Сочувствуете и поддерживаете","value":"F"}]},
    {"id":42,"text":"В отношениях с людьми важнее:","dimension":"TF","type":"bipolar","options":[{"text":"Честность, даже если она ранит","value":"T"},{"text":"Гармония и доброта","value":"F"}]},
    {"id":43,"text":"При оценке ситуации вы сначала думаете о:","dimension":"TF","type":"bipolar","options":[{"text":"Логических последствиях","value":"T"},{"text":"Людях, которых это затронет","value":"F"}]},
    {"id":44,"text":"Когда кто-то расстроен, вы:","dimension":"TF","type":"bipolar","options":[{"text":"Пытаетесь помочь решить проблему","value":"T"},{"text":"Просто сидите рядом и поддерживаете","value":"F"}]},
    {"id":45,"text":"Вам комфортнее когда всё:","dimension":"TF","type":"bipolar","options":[{"text":"Определённо и чётко","value":"T"},{"text":"Тепло и гармонично","value":"F"}]},
    {"id":46,"text":"Вы предпочитаете:","dimension":"JP","type":"bipolar","options":[{"text":"Иметь чёткий план","value":"J"},{"text":"Действовать по ситуации","value":"P"}]},
    {"id":47,"text":"Вас раздражает, когда:","dimension":"JP","type":"bipolar","options":[{"text":"Всё меняется в последний момент","value":"J"},{"text":"Жёсткие рамки и правила","value":"P"}]},
    {"id":48,"text":"Рабочий стол у вас обычно:","dimension":"JP","type":"bipolar","options":[{"text":"Порядок, каждая вещь на месте","value":"J"},{"text":"Творческий беспорядок","value":"P"}]},
    {"id":49,"text":"Вы предпочитаете:","dimension":"JP","type":"bipolar","options":[{"text":"Завершать дела до дедлайна","value":"J"},{"text":"Работать лучше под давлением дедлайна","value":"P"}]},
    {"id":50,"text":"Принимая решение, вы:","dimension":"JP","type":"bipolar","options":[{"text":"Быстро решаете и придерживаетесь этого","value":"J"},{"text":"Долго взвешиваете варианты","value":"P"}]},
    {"id":51,"text":"Вы чувствуете себя лучше, когда:","dimension":"JP","type":"bipolar","options":[{"text":"Вопрос решён и закрыт","value":"J"},{"text":"Есть свобода менять решения","value":"P"}]},
    {"id":52,"text":"На отдыхе вы:","dimension":"JP","type":"bipolar","options":[{"text":"Заранее планируете маршрут","value":"J"},{"text":"Едете без особого плана","value":"P"}]},
    {"id":53,"text":"Важные дела вы:","dimension":"JP","type":"bipolar","options":[{"text":"Делаете заблаговременно","value":"J"},{"text":"Откладываете до последнего","value":"P"}]},
    {"id":54,"text":"Вы предпочитаете:","dimension":"JP","type":"bipolar","options":[{"text":"Расписание и структуру","value":"J"},{"text":"Гибкость и открытость","value":"P"}]},
    {"id":55,"text":"Незаконченные дела вас:","dimension":"JP","type":"bipolar","options":[{"text":"Беспокоят","value":"J"},{"text":"Совершенно не напрягают","value":"P"}]},
    {"id":56,"text":"При выборе между двумя вариантами вы:","dimension":"JP","type":"bipolar","options":[{"text":"Быстро выбираете и не сожалеете","value":"J"},{"text":"Хотите попробовать оба","value":"P"}]},
    {"id":57,"text":"В путешествии вы:","dimension":"JP","type":"bipolar","options":[{"text":"Бронируете отель заранее","value":"J"},{"text":"Ищете жильё на месте","value":"P"}]},
    {"id":58,"text":"Ваш стиль жизни скорее:","dimension":"JP","type":"bipolar","options":[{"text":"Упорядоченный и стабильный","value":"J"},{"text":"Разнообразный и спонтанный","value":"P"}]},
    {"id":59,"text":"Вам комфортнее когда:","dimension":"JP","type":"bipolar","options":[{"text":"Есть определённость","value":"J"},{"text":"Есть пространство для манёвра","value":"P"}]},
    {"id":60,"text":"В жизни важнее:","dimension":"JP","type":"bipolar","options":[{"text":"Порядок и предсказуемость","value":"J"},{"text":"Свобода и гибкость","value":"P"}]}
  ]'::jsonb,
  '{"formula":"mbti","dimensions":["EI","SN","TF","JP"]}'::jsonb,
  '{
    "INTJ":{"name":"Архитектор","description":"Стратег с богатым воображением. Уверен в себе и аналитичен. Высокие стандарты к себе и другим.","strengths":["Стратегическое мышление","Независимость","Решительность","Целеустремлённость"]},
    "INTP":{"name":"Логик","description":"Мыслитель, жаждущий знаний. Оригинален и изобретателен. Ценит логику.","strengths":["Аналитическое мышление","Объективность","Открытость идеям","Точность"]},
    "ENTJ":{"name":"Командир","description":"Смелый и волевой лидер. Находит или создаёт решения для любой проблемы.","strengths":["Лидерство","Стратегическое планирование","Уверенность","Эффективность"]},
    "ENTP":{"name":"Полемист","description":"Умный и любопытный. Не может противостоять интеллектуальному вызову.","strengths":["Инновации","Стратегическое мышление","Красноречие","Энергичность"]},
    "INFJ":{"name":"Активист","description":"Тихий и мистичный, но вдохновляющий идеализмом. Один из редких типов.","strengths":["Прозорливость","Принципиальность","Страстность","Альтруизм"]},
    "INFP":{"name":"Посредник","description":"Поэтичный, добрый и альтруистичный. Всегда готов помочь хорошему делу.","strengths":["Эмпатия","Открытость","Творчество","Страстность"]},
    "ENFJ":{"name":"Тренер","description":"Харизматичный и вдохновляющий. Способен зажечь других своей идеей.","strengths":["Лидерство","Харизма","Сочувствие","Надёжность"]},
    "ENFP":{"name":"Борец","description":"Жизнерадостный и творческий. Видит жизнь наполненной возможностями.","strengths":["Энтузиазм","Творчество","Коммуникабельность","Эмпатия"]},
    "ISTJ":{"name":"Администратор","description":"Практичный и ответственный. Выполняет обязательства несмотря ни на что.","strengths":["Надёжность","Усидчивость","Практичность","Честность"]},
    "ISFJ":{"name":"Защитник","description":"Тихий и дружелюбный. Очень ответственный и добросовестный.","strengths":["Поддержка","Надёжность","Терпение","Преданность"]},
    "ESTJ":{"name":"Руководитель","description":"Исключительный организатор. Чёткое представление о правильном и неправильном.","strengths":["Организация","Преданность","Целеустремлённость","Честность"]},
    "ESFJ":{"name":"Консул","description":"Исключительно заботливый. Ценит гармонию и сотрудничество.","strengths":["Поддержка","Надёжность","Практичность","Лояльность"]},
    "ISTP":{"name":"Виртуоз","description":"Смелый эксперт. Обожает разбираться в том, как работают вещи.","strengths":["Оптимизм","Практичность","Мастерство","Непосредственность"]},
    "ISFP":{"name":"Авантюрист","description":"Гибкий и обаятельный. Всегда готов к новым исследованиям.","strengths":["Обаяние","Артистизм","Страстность","Любопытство"]},
    "ESTP":{"name":"Делец","description":"Умный и энергичный. Воспринимает жизнь как шанс и живёт настоящим.","strengths":["Прямота","Решительность","Обаяние","Смелость"]},
    "ESFP":{"name":"Развлекатель","description":"Спонтанный и энергичный. Жизнь никогда не скучна рядом с ESFP.","strengths":["Энтузиазм","Практичность","Обаяние","Наблюдательность"]}
  }'::jsonb
);

