INSERT INTO public.tests (slug, title, description, category, estimated_minutes, questions, scoring, result_types)
VALUES (
  'big-five',
  'Большая пятёрка (OCEAN)',
  'Тест BFI-44 измеряет 5 базовых черт личности: Открытость, Добросовестность, Экстраверсия, Доброжелательность, Нейротизм.',
  'personality',
  20,
  '[
    {"id":1,"text":"Я вижу себя как человека, который разговорчив","factor":"E","reverse":false,"type":"scale"},
    {"id":2,"text":"Я вижу себя как человека, который склонен находить недостатки в других","factor":"A","reverse":true,"type":"scale"},
    {"id":3,"text":"Я вижу себя как человека, который тщательно и добросовестно выполняет работу","factor":"C","reverse":false,"type":"scale"},
    {"id":4,"text":"Я вижу себя как человека, который подавлен, грустит","factor":"N","reverse":false,"type":"scale"},
    {"id":5,"text":"Я вижу себя как человека, который оригинален, придумывает новые идеи","factor":"O","reverse":false,"type":"scale"},
    {"id":6,"text":"Я вижу себя как человека, который сдержан","factor":"E","reverse":true,"type":"scale"},
    {"id":7,"text":"Я вижу себя как человека, который готов помочь и не эгоистичен","factor":"A","reverse":false,"type":"scale"},
    {"id":8,"text":"Я вижу себя как человека, который может быть несколько небрежен","factor":"C","reverse":true,"type":"scale"},
    {"id":9,"text":"Я вижу себя как человека, который спокоен, хорошо справляется со стрессом","factor":"N","reverse":true,"type":"scale"},
    {"id":10,"text":"Я вижу себя как человека, который любознателен в отношении многих разных вещей","factor":"O","reverse":false,"type":"scale"},
    {"id":11,"text":"Я вижу себя как человека, который полон энергии","factor":"E","reverse":false,"type":"scale"},
    {"id":12,"text":"Я вижу себя как человека, который начинает ссоры с другими","factor":"A","reverse":true,"type":"scale"},
    {"id":13,"text":"Я вижу себя как человека, который надёжен, на него можно положиться","factor":"C","reverse":false,"type":"scale"},
    {"id":14,"text":"Я вижу себя как человека, который бывает напряжён","factor":"N","reverse":false,"type":"scale"},
    {"id":15,"text":"Я вижу себя как человека, который вдумчив и любит рефлексировать","factor":"O","reverse":false,"type":"scale"},
    {"id":16,"text":"Я вижу себя как человека, который генерирует много энтузиазма","factor":"E","reverse":false,"type":"scale"},
    {"id":17,"text":"Я вижу себя как человека, который прощает и снисходителен к другим","factor":"A","reverse":false,"type":"scale"},
    {"id":18,"text":"Я вижу себя как человека, который склонен к дезорганизации","factor":"C","reverse":true,"type":"scale"},
    {"id":19,"text":"Я вижу себя как человека, который много беспокоится","factor":"N","reverse":false,"type":"scale"},
    {"id":20,"text":"Я вижу себя как человека, который обладает богатым воображением","factor":"O","reverse":false,"type":"scale"},
    {"id":21,"text":"Я вижу себя как человека, который склонен молчать","factor":"E","reverse":true,"type":"scale"},
    {"id":22,"text":"Я вижу себя как человека, который в целом доверяет людям","factor":"A","reverse":false,"type":"scale"},
    {"id":23,"text":"Я вижу себя как человека, который ленится","factor":"C","reverse":true,"type":"scale"},
    {"id":24,"text":"Я вижу себя как человека, который эмоционально стабилен, которого трудно расстроить","factor":"N","reverse":true,"type":"scale"},
    {"id":25,"text":"Я вижу себя как человека, который изобретателен","factor":"O","reverse":false,"type":"scale"},
    {"id":26,"text":"Я вижу себя как человека, который умеет заявить о себе","factor":"E","reverse":false,"type":"scale"},
    {"id":27,"text":"Я вижу себя как человека, который бывает холодным и отстранённым","factor":"A","reverse":true,"type":"scale"},
