-- TEST 3: Eysenck EPI (57 yes/no)
-- ============================================================
INSERT INTO public.tests (slug, title, description, category, estimated_minutes, questions, scoring, result_types)
VALUES (
  'eysenck',
  'Тест Айзенка (EPI)',
  'Личностный опросник Айзенка выявляет три шкалы: Экстраверсия-Интроверсия, Нейротизм и Ложь (социальная желательность).',
  'personality',
  20,
  '[
    {"id":1,"text":"Часто ли вы испытываете тягу к острым ощущениям?","scale":"E","key":"yes","type":"yesno"},
    {"id":2,"text":"Часто ли вам требуется, чтобы внимательные друзья ободрили вас?","scale":"N","key":"yes","type":"yesno"},
    {"id":3,"text":"Вы обычно беззаботный человек?","scale":"E","key":"yes","type":"yesno"},
    {"id":4,"text":"Трудно ли вам отказать людям?","scale":"N","key":"yes","type":"yesno"},
    {"id":5,"text":"Задумываетесь ли вы перед тем, как что-то предпринять?","scale":"E","key":"no","type":"yesno"},
    {"id":6,"text":"Если вы пообещали что-то сделать, всегда ли вы сдерживаете обещание?","scale":"L","key":"yes","type":"yesno"},
    {"id":7,"text":"Часто ли у вас бывают взлёты и падения настроения?","scale":"N","key":"yes","type":"yesno"},
    {"id":8,"text":"Обычно вы действуете и говорите быстро, не задумываясь?","scale":"E","key":"yes","type":"yesno"},
    {"id":9,"text":"Случалось ли вам чувствовать себя несчастным без всякой причины?","scale":"N","key":"yes","type":"yesno"},
    {"id":10,"text":"Сделали бы вы почти всё что угодно на спор?","scale":"E","key":"yes","type":"yesno"},
    {"id":11,"text":"Возникает ли у вас вдруг чувство застенчивости и неловкости, когда вы хотите заговорить с симпатичным незнакомцем?","scale":"N","key":"yes","type":"yesno"},
    {"id":12,"text":"Иногда вы выходите из себя?","scale":"L","key":"no","type":"yesno"},
    {"id":13,"text":"Часто ли вы действуете под влиянием минутного настроения?","scale":"E","key":"yes","type":"yesno"},
    {"id":14,"text":"Часто ли вы беспокоитесь из-за того, что сделали или сказали что-то, чего не следовало?","scale":"N","key":"yes","type":"yesno"},
    {"id":15,"text":"Предпочитаете ли вы книги встречам с людьми?","scale":"E","key":"no","type":"yesno"},
    {"id":16,"text":"Обидеть вас довольно легко?","scale":"N","key":"yes","type":"yesno"},
    {"id":17,"text":"Любите ли вы часто бывать в компаниях?","scale":"E","key":"yes","type":"yesno"},
    {"id":18,"text":"Бывают ли у вас такие мысли, которыми вам не хотелось бы делиться?","scale":"L","key":"no","type":"yesno"},
    {"id":19,"text":"Случается ли, что вы настолько полны энергии, что всё горит в руках, а иногда чувствуете сильную вялость?","scale":"N","key":"yes","type":"yesno"},
    {"id":20,"text":"Предпочитаете ли вы иметь поменьше друзей, но особенно близких?","scale":"E","key":"no","type":"yesno"},
    {"id":21,"text":"Часто ли вы мечтаете?","scale":"N","key":"yes","type":"yesno"},
    {"id":22,"text":"Когда на вас кричат, отвечаете ли вы тем же?","scale":"L","key":"no","type":"yesno"},
    {"id":23,"text":"Часто ли вас беспокоит чувство вины?","scale":"N","key":"yes","type":"yesno"},
    {"id":24,"text":"Все ли ваши привычки хороши?","scale":"L","key":"yes","type":"yesno"},
    {"id":25,"text":"Способны ли вы дать волю своим чувствам и вволю повеселиться в шумной компании?","scale":"E","key":"yes","type":"yesno"},
    {"id":26,"text":"Считаете ли вы себя человеком, у которого нервы натянуты до предела?","scale":"N","key":"yes","type":"yesno"},
    {"id":27,"text":"Считают ли вас человеком живым и весёлым?","scale":"E","key":"yes","type":"yesno"},
    {"id":28,"text":"После того как дело сделано, часто ли вы мысленно возвращаетесь к нему и думаете, что могли бы сделать лучше?","scale":"N","key":"yes","type":"yesno"},
    {"id":29,"text":"Когда вы находитесь в обществе людей, чувствуете ли вы себя обычно тихим и замкнутым?","scale":"E","key":"no","type":"yesno"},
    {"id":30,"text":"Бывает ли, что вы сплетничаете?","scale":"L","key":"no","type":"yesno"},
    {"id":31,"text":"Бывает ли, что вам не спится из-за тревожных мыслей?","scale":"N","key":"yes","type":"yesno"},
    {"id":32,"text":"Если вы хотите узнать о чём-то, то предпочитаете прочитать об этом в книге, а не спросить?","scale":"E","key":"no","type":"yesno"},
    {"id":33,"text":"Бывают ли у вас сильные сердцебиения?","scale":"N","key":"yes","type":"yesno"},
    {"id":34,"text":"Нравится ли вам работа, требующая от вас постоянного внимания?","scale":"E","key":"no","type":"yesno"},
    {"id":35,"text":"Бывают ли у вас приступы дрожи?","scale":"N","key":"yes","type":"yesno"},
    {"id":36,"text":"Всегда ли вы платили бы за провоз вещей в транспорте, если бы не опасались проверки?","scale":"L","key":"yes","type":"yesno"},
    {"id":37,"text":"Неприятно ли вам находиться в обществе, где подшучивают друг над другом?","scale":"E","key":"no","type":"yesno"},
    {"id":38,"text":"Раздражительны ли вы?","scale":"N","key":"yes","type":"yesno"},
    {"id":39,"text":"Нравится ли вам работа, требующая быстроты?","scale":"E","key":"yes","type":"yesno"},
    {"id":40,"text":"Волнуетесь ли вы по поводу каких-то неприятных событий, которые могли бы произойти?","scale":"N","key":"yes","type":"yesno"},
    {"id":41,"text":"Вы ходите неторопливо и неспешно?","scale":"E","key":"no","type":"yesno"},
    {"id":42,"text":"Вы когда-нибудь опаздывали на свидание или на работу?","scale":"L","key":"no","type":"yesno"},
    {"id":43,"text":"Часто ли вам снятся кошмары?","scale":"N","key":"yes","type":"yesno"},
    {"id":44,"text":"Верно ли, что вы так любите поговорить, что не упускаете ни одного случая побеседовать с незнакомым человеком?","scale":"E","key":"yes","type":"yesno"},
    {"id":45,"text":"Беспокоят ли вас какие-нибудь боли?","scale":"N","key":"yes","type":"yesno"},
    {"id":46,"text":"Почувствовали бы вы себя очень несчастным, если бы длительное время были лишены широкого общения с людьми?","scale":"E","key":"yes","type":"yesno"},
    {"id":47,"text":"Можете ли вы назвать себя нервным человеком?","scale":"N","key":"yes","type":"yesno"},
    {"id":48,"text":"Есть ли среди ваших знакомых люди, которые вам явно не нравятся?","scale":"L","key":"no","type":"yesno"},
    {"id":49,"text":"Можете ли вы назвать себя достаточно уверенным в себе человеком?","scale":"E","key":"yes","type":"yesno"},
    {"id":50,"text":"Легко ли вас задевает критика ваших недостатков или вашей работы?","scale":"N","key":"yes","type":"yesno"},
    {"id":51,"text":"Трудно ли вам получить настоящее удовольствие от вечеринок?","scale":"E","key":"no","type":"yesno"},
    {"id":52,"text":"Беспокоит ли вас ощущение, что вы чем-то хуже других?","scale":"N","key":"yes","type":"yesno"},
    {"id":53,"text":"Смогли бы вы оживить скучную вечеринку?","scale":"E","key":"yes","type":"yesno"},
    {"id":54,"text":"Случается ли вам говорить о вещах, в которых вы совсем не разбираетесь?","scale":"L","key":"no","type":"yesno"},
    {"id":55,"text":"Беспокоитесь ли вы о своём здоровье?","scale":"N","key":"yes","type":"yesno"},
    {"id":56,"text":"Любите ли вы подшучивать над другими?","scale":"E","key":"yes","type":"yesno"},
    {"id":57,"text":"Страдаете ли вы от бессонницы?","scale":"N","key":"yes","type":"yesno"}
  ]'::jsonb,
  '{"formula":"eysenck","scales":["E","N","L"]}'::jsonb,
  '{
    "EH_NH":{"name":"Холерик","description":"Высокая экстраверсия и высокий нейротизм. Активный, оптимистичный, импульсивный, изменчивый."},
    "EH_NL":{"name":"Сангвиник","description":"Высокая экстраверсия и низкий нейротизм. Общительный, беззаботный, лидер, живой."},
    "EL_NH":{"name":"Меланхолик","description":"Низкая экстраверсия и высокий нейротизм. Тревожный, ригидный, тихий, пессимистичный."},
    "EL_NL":{"name":"Флегматик","description":"Низкая экстраверсия и низкий нейротизм. Пассивный, осторожный, рассудительный, спокойный."}
  }'::jsonb
);

