      {"id":"gray","hex":"#808080","name":"Серый"},
      {"id":"blue","hex":"#003399","name":"Синий"},
      {"id":"green","hex":"#00963A","name":"Зелёный"},
      {"id":"red","hex":"#CC0000","name":"Красный"},
      {"id":"yellow","hex":"#FFFF00","name":"Жёлтый"},
      {"id":"purple","hex":"#7A2B85","name":"Фиолетовый"},
