INSERT INTO public.tests (slug, title, description, category, estimated_minutes, questions, scoring, result_types)
VALUES (
  'spielberger',
  'Тест Спилбергера-Ханина (тревожность)',
  'Измеряет два вида тревожности: ситуативную (как вы себя чувствуете сейчас) и личностную (как вы себя чувствуете обычно).',
  'emotion',
  15,
  '[
    {"id":1,"text":"Я спокоен","scale":"state","reverse":true,"type":"scale4"},
    {"id":2,"text":"Мне ничто не угрожает","scale":"state","reverse":true,"type":"scale4"},
    {"id":3,"text":"Я нахожусь в напряжении","scale":"state","reverse":false,"type":"scale4"},
    {"id":4,"text":"Я испытываю сожаление","scale":"state","reverse":false,"type":"scale4"},
    {"id":5,"text":"Я чувствую себя свободно","scale":"state","reverse":true,"type":"scale4"},
    {"id":6,"text":"Я расстроен","scale":"state","reverse":false,"type":"scale4"},
    {"id":7,"text":"Меня волнуют возможные неудачи","scale":"state","reverse":false,"type":"scale4"},
    {"id":8,"text":"Я чувствую себя отдохнувшим","scale":"state","reverse":true,"type":"scale4"},
    {"id":9,"text":"Я встревожен","scale":"state","reverse":false,"type":"scale4"},
    {"id":10,"text":"Я испытываю чувство внутреннего удовлетворения","scale":"state","reverse":true,"type":"scale4"},
    {"id":11,"text":"Я уверен в себе","scale":"state","reverse":true,"type":"scale4"},
    {"id":12,"text":"Я нервничаю","scale":"state","reverse":false,"type":"scale4"},
    {"id":13,"text":"Я не нахожу себе места","scale":"state","reverse":false,"type":"scale4"},
    {"id":14,"text":"Я взвинчен","scale":"state","reverse":false,"type":"scale4"},
    {"id":15,"text":"Я не чувствую скованности, напряжения","scale":"state","reverse":true,"type":"scale4"},
    {"id":16,"text":"Я доволен","scale":"state","reverse":true,"type":"scale4"},
    {"id":17,"text":"Я озабочен","scale":"state","reverse":false,"type":"scale4"},
    {"id":18,"text":"Я слишком возбуждён и мне не по себе","scale":"state","reverse":false,"type":"scale4"},
    {"id":19,"text":"Мне радостно","scale":"state","reverse":true,"type":"scale4"},
    {"id":20,"text":"Мне приятно","scale":"state","reverse":true,"type":"scale4"},
    {"id":21,"text":"Я испытываю удовольствие","scale":"trait","reverse":true,"type":"scale4"},
    {"id":22,"text":"Я обычно быстро устаю","scale":"trait","reverse":false,"type":"scale4"},
    {"id":23,"text":"Я легко плачу","scale":"trait","reverse":false,"type":"scale4"},
    {"id":24,"text":"Я хотел бы быть таким же счастливым, как другие","scale":"trait","reverse":false,"type":"scale4"},
    {"id":25,"text":"Я проигрываю, потому что недостаточно быстро принимаю решения","scale":"trait","reverse":false,"type":"scale4"},
    {"id":26,"text":"Я чувствую себя бодрым","scale":"trait","reverse":true,"type":"scale4"},
    {"id":27,"text":"Я спокоен, хладнокровен и собран","scale":"trait","reverse":true,"type":"scale4"},
    {"id":28,"text":"Ожидаемые трудности обычно сильно тревожат меня","scale":"trait","reverse":false,"type":"scale4"},
    {"id":29,"text":"Я слишком переживаю из-за пустяков","scale":"trait","reverse":false,"type":"scale4"},
    {"id":30,"text":"Я вполне счастлив","scale":"trait","reverse":true,"type":"scale4"},
    {"id":31,"text":"Я принимаю всё слишком близко к сердцу","scale":"trait","reverse":false,"type":"scale4"},
    {"id":32,"text":"Мне не хватает уверенности в себе","scale":"trait","reverse":false,"type":"scale4"},
    {"id":33,"text":"Я чувствую себя в безопасности","scale":"trait","reverse":true,"type":"scale4"},
    {"id":34,"text":"Я стараюсь избегать критических ситуаций и трудностей","scale":"trait","reverse":false,"type":"scale4"},
    {"id":35,"text":"У меня бывает хандра","scale":"trait","reverse":false,"type":"scale4"},
    {"id":36,"text":"Я доволен","scale":"trait","reverse":true,"type":"scale4"},
    {"id":37,"text":"Всякие пустяки отвлекают и волнуют меня","scale":"trait","reverse":false,"type":"scale4"},
    {"id":38,"text":"Я так сильно переживаю свои разочарования, что потом долго не могу о них забыть","scale":"trait","reverse":false,"type":"scale4"},
    {"id":39,"text":"Я уравновешенный человек","scale":"trait","reverse":true,"type":"scale4"},
    {"id":40,"text":"Меня охватывает сильное беспокойство, когда я думаю о своих делах и заботах","scale":"trait","reverse":false,"type":"scale4"}
  ]'::jsonb,
  '{"formula":"spielberger","scales":["state","trait"],"options":[{"value":1,"text":"Совсем нет"},{"value":2,"text":"Немного"},{"value":3,"text":"Умеренно"},{"value":4,"text":"Очень сильно"}]}'::jsonb,
  '{
    "low":{"range":[20,30],"label":"Низкая тревожность","description":"Вы спокойны и уверены в себе. Низкая тревожность может снижать мотивацию."},
    "medium":{"range":[31,44],"label":"Умеренная тревожность","description":"Оптимальный уровень тревоги. Помогает мобилизоваться и быть эффективным."},
    "high":{"range":[45,80],"label":"Высокая тревожность","description":"Повышенный уровень тревоги. Рекомендуется работа с психологом или техники релаксации."}
  }'::jsonb
);

-- ============================================================
-- TEST 6: Beck Depression Inventory BDI (21 questions)
-- ============================================================
INSERT INTO public.tests (slug, title, description, category, estimated_minutes, questions, scoring, result_types)
VALUES (
  'beck',
  'Тест депрессии Бека (BDI)',
  'Опросник Бека — стандартная методика для оценки уровня депрессии. Для каждого пункта выберите утверждение, наиболее точно описывающее ваше состояние.',
  'emotion',
  15,
  '[
    {"id":1,"text":"Настроение","type":"multichoice","options":[{"value":0,"text":"Я не чувствую себя расстроенным или подавленным"},{"value":1,"text":"Я чувствую себя расстроенным"},{"value":2,"text":"Я постоянно расстроен и не могу отвлечься"},{"value":3,"text":"Я настолько несчастен и расстроен, что не могу этого вынести"}]},
    {"id":2,"text":"Пессимизм","type":"multichoice","options":[{"value":0,"text":"Я не чувствую себя особенно обескураженным"},{"value":1,"text":"Я чувствую себя обескураженным, когда думаю о будущем"},{"value":2,"text":"Я чувствую, что мне нечего ждать от будущего"},{"value":3,"text":"Будущее безнадёжно, и ничто не может измениться к лучшему"}]},
    {"id":3,"text":"Ощущение неудачи","type":"multichoice","options":[{"value":0,"text":"Я не чувствую себя неудачником"},{"value":1,"text":"Мне кажется, что я потерпел больше неудач, чем другие люди"},{"value":2,"text":"Когда я оглядываюсь назад, я вижу в своей жизни много неудач"},{"value":3,"text":"Я чувствую, что как личность я — полный неудачник"}]},
    {"id":4,"text":"Неудовлетворённость","type":"multichoice","options":[{"value":0,"text":"Я получаю столько же удовольствия от жизни, как раньше"},{"value":1,"text":"Я не получаю столько же удовольствия от жизни, как раньше"},{"value":2,"text":"Я больше не получаю удовольствия ни от чего"},{"value":3,"text":"Меня всё раздражает, и я совсем не способен испытывать удовольствие"}]},
    {"id":5,"text":"Чувство вины","type":"multichoice","options":[{"value":0,"text":"Я не чувствую особой вины"},{"value":1,"text":"Временами я чувствую себя виноватым"},{"value":2,"text":"Я нередко чувствую себя виноватым"},{"value":3,"text":"Теперь я постоянно ощущаю свою вину"}]},
    {"id":6,"text":"Ощущение наказания","type":"multichoice","options":[{"value":0,"text":"Я не чувствую, что могу быть наказан"},{"value":1,"text":"Я чувствую, что могу быть наказан"},{"value":2,"text":"Я ожидаю наказания"},{"value":3,"text":"Я чувствую, что уже наказан"}]},
    {"id":7,"text":"Самонеудовлетворённость","type":"multichoice","options":[{"value":0,"text":"Я не разочарован в себе"},{"value":1,"text":"Я разочарован в себе"},{"value":2,"text":"Я себе противен"},{"value":3,"text":"Я себя ненавижу"}]},
    {"id":8,"text":"Самообвинение","type":"multichoice","options":[{"value":0,"text":"Я не чувствую, что я хуже других людей"},{"value":1,"text":"Я критикую себя за слабости и ошибки"},{"value":2,"text":"Я постоянно упрекаю себя за свои поступки"},{"value":3,"text":"Я виню себя во всём плохом, что происходит"}]},
    {"id":9,"text":"Суицидальные мысли","type":"multichoice","options":[{"value":0,"text":"Мне никогда не приходят мысли о самоубийстве"},{"value":1,"text":"Иногда такие мысли приходят, но я им не следую"},{"value":2,"text":"Суицидальные мысли посещают меня нередко"},{"value":3,"text":"У меня есть определённые планы о самоубийстве"}]},
    {"id":10,"text":"Плаксивость","type":"multichoice","options":[{"value":0,"text":"Я плачу не больше обычного"},{"value":1,"text":"Теперь я плачу больше, чем раньше"},{"value":2,"text":"Теперь я плачу постоянно"},{"value":3,"text":"Раньше я мог плакать, но теперь не могу, даже если хочу"}]},
    {"id":11,"text":"Раздражительность","type":"multichoice","options":[{"value":0,"text":"Я не более раздражителен, чем обычно"},{"value":1,"text":"Я легче раздражаюсь, чем раньше"},{"value":2,"text":"Я всё время раздражён"},{"value":3,"text":"Меня уже не раздражает то, что раздражало раньше"}]},
    {"id":12,"text":"Социальная отстранённость","type":"multichoice","options":[{"value":0,"text":"Я не утратил интереса к другим людям"},{"value":1,"text":"Я стал меньше интересоваться другими людьми"},{"value":2,"text":"Я утратил почти весь интерес к другим людям"},{"value":3,"text":"Другие люди меня не интересуют"}]},
    {"id":13,"text":"Нерешительность","type":"multichoice","options":[{"value":0,"text":"Я принимаю решения так же хорошо, как всегда"},{"value":1,"text":"Теперь я хуже принимаю решения"},{"value":2,"text":"Мне стало значительно труднее принимать решения"},{"value":3,"text":"Я вообще не могу принимать решения"}]},
    {"id":14,"text":"Образ тела","type":"multichoice","options":[{"value":0,"text":"Я не думаю, что выгляжу хуже, чем обычно"},{"value":1,"text":"Меня беспокоит, что я выгляжу старым и непривлекательным"},{"value":2,"text":"Я чувствую, что в моей внешности произошли необратимые изменения"},{"value":3,"text":"Я уверен, что выгляжу безобразно"}]},
    {"id":15,"text":"Работоспособность","type":"multichoice","options":[{"value":0,"text":"Я работаю так же хорошо, как и раньше"},{"value":1,"text":"Теперь мне стоит большего труда начать что-то делать"},{"value":2,"text":"Мне очень трудно заставить себя что-то сделать"},{"value":3,"text":"Я совсем не могу работать"}]},
    {"id":16,"text":"Сон","type":"multichoice","options":[{"value":0,"text":"Я сплю так же хорошо, как и раньше"},{"value":1,"text":"Теперь я сплю хуже, чем прежде"},{"value":2,"text":"Я просыпаюсь на 1-2 часа раньше и с трудом засыпаю снова"},{"value":3,"text":"Я просыпаюсь на несколько часов раньше и не могу заснуть"}]},
    {"id":17,"text":"Усталость","type":"multichoice","options":[{"value":0,"text":"Я устаю не больше, чем обычно"},{"value":1,"text":"Теперь я устаю быстрее, чем раньше"},{"value":2,"text":"Почти от любого дела я устаю"},{"value":3,"text":"Я слишком устал, чтобы что-нибудь делать"}]},
    {"id":18,"text":"Аппетит","type":"multichoice","options":[{"value":0,"text":"Мой аппетит ничуть не хуже, чем обычно"},{"value":1,"text":"Мой аппетит стал хуже, чем раньше"},{"value":2,"text":"Мой аппетит теперь значительно хуже"},{"value":3,"text":"У меня вообще нет аппетита"}]},
    {"id":19,"text":"Потеря веса","type":"multichoice","options":[{"value":0,"text":"За последнее время я почти не похудел"},{"value":1,"text":"Я похудел более чем на 2 кг"},{"value":2,"text":"Я похудел более чем на 5 кг"},{"value":3,"text":"Я похудел более чем на 7 кг"}]},
    {"id":20,"text":"Озабоченность здоровьем","type":"multichoice","options":[{"value":0,"text":"Я беспокоюсь о своём здоровье не больше, чем обычно"},{"value":1,"text":"Меня беспокоят мелкие недомогания"},{"value":2,"text":"Я сильно обеспокоен своим здоровьем"},{"value":3,"text":"Я настолько обеспокоен своим состоянием, что не могу думать ни о чём другом"}]},
    {"id":21,"text":"Сексуальный интерес","type":"multichoice","options":[{"value":0,"text":"Я не замечаю изменений в своём сексуальном интересе"},{"value":1,"text":"Я меньше интересуюсь сексом, чем раньше"},{"value":2,"text":"Теперь я значительно меньше интересуюсь сексом"},{"value":3,"text":"Я полностью утратил сексуальный интерес"}]}
  ]'::jsonb,
  '{"formula":"beck","min":0,"max":63}'::jsonb,
  '{
    "minimal":{"range":[0,13],"label":"Минимальная депрессия","description":"Состояние в норме. Незначительные колебания настроения естественны."},
    "mild":{"range":[14,19],"label":"Лёгкая депрессия","description":"Мягкая депрессия. Рекомендуется обратить внимание на самочувствие."},
    "moderate":{"range":[20,28],"label":"Умеренная депрессия","description":"Умеренная депрессия. Рекомендуется консультация специалиста."},
    "severe":{"range":[29,63],"label":"Тяжёлая депрессия","description":"Выраженная депрессия. Необходима помощь специалиста."}
  }'::jsonb
);

-- ============================================================
-- TEST 7: Rotter Locus of Control (29 pairs)
-- ============================================================
INSERT INTO public.tests (slug, title, description, category, estimated_minutes, questions, scoring, result_types)
VALUES (
  'rotter',
  'Тест Роттера (локус контроля)',
  'Опросник Дж. Роттера измеряет локус контроля — убеждение человека в том, что он сам управляет своей жизнью или зависит от внешних обстоятельств.',
  'cognitive',
  15,
  '[
    {"id":1,"text":"","type":"pair","options":[{"text":"Дети попадают в неприятности потому, что родители слишком их наказывают","value":"E"},{"text":"В наши дни родители всё меньше контролируют своих детей","value":"I"}]},
    {"id":2,"text":"","type":"pair","options":[{"text":"Многие неудачи происходят из-за невезения","value":"E"},{"text":"Люди терпят поражение потому, что не достаточно трудятся","value":"I"}]},
    {"id":3,"text":"","type":"pair","options":[{"text":"Войны будут всегда — так уж устроен мир","value":"E"},{"text":"Люди могут добиться мира, если будут усердно к нему стремиться","value":"I"}]},
    {"id":4,"text":"","type":"pair","options":[{"text":"Рано или поздно можно найти подходящего человека","value":"I"},{"text":"Конечно, самим подходящим людям трудно найти пару","value":"E"}]},
    {"id":5,"text":"","type":"pair","options":[{"text":"Что бы я ни делал, всё равно ничего не изменится","value":"E"},{"text":"Я не понимаю мнения, что нельзя влиять на мировые события","value":"I"}]},
    {"id":6,"text":"","type":"pair","options":[{"text":"Учителя несправедливы к ученикам без всяких причин","value":"E"},{"text":"Большинство трудностей учеников в школе связаны с тем, что они не стараются","value":"I"}]},
    {"id":7,"text":"","type":"pair","options":[{"text":"То, что произойдёт — всё равно произойдёт","value":"E"},{"text":"Целеустремлённость всегда вознаграждается","value":"I"}]},
    {"id":8,"text":"","type":"pair","options":[{"text":"Настоящий лидер рождается, а не становится","value":"E"},{"text":"Умение руководить — результат обучения и практики","value":"I"}]},
    {"id":9,"text":"","type":"pair","options":[{"text":"Обычные люди не могут влиять на решения правительства","value":"E"},{"text":"Люди сами несут ответственность за своё правительство","value":"I"}]},
    {"id":10,"text":"","type":"pair","options":[{"text":"Я нахожу связь между упорством и успехом","value":"I"},{"text":"Успех зависит от удачного стечения обстоятельств","value":"E"}]},
    {"id":11,"text":"","type":"pair","options":[{"text":"Судьбы большинства людей определяются случайностью","value":"E"},{"text":"Человек сам творит свою судьбу","value":"I"}]},
    {"id":12,"text":"","type":"pair","options":[{"text":"Когда я строю планы, я почти уверен, что осуществлю их","value":"I"},{"text":"Планировать наперёд — бесполезное занятие","value":"E"}]},
    {"id":13,"text":"","type":"pair","options":[{"text":"Есть такие люди, у которых нет никаких достоинств","value":"E"},{"text":"В каждом можно найти что-то хорошее","value":"I"}]},
    {"id":14,"text":"","type":"pair","options":[{"text":"Я убеждён, что моё обращение с другими зависит только от меня","value":"I"},{"text":"Человеку трудно контролировать своё поведение","value":"E"}]},
    {"id":15,"text":"","type":"pair","options":[{"text":"Способные люди всегда найдут хорошую работу","value":"I"},{"text":"На рынке труда решает случай","value":"E"}]},
    {"id":16,"text":"","type":"pair","options":[{"text":"Мои оценки в школе зависели от моих усилий","value":"I"},{"text":"Оценки зависели от настроения преподавателя","value":"E"}]},
    {"id":17,"text":"","type":"pair","options":[{"text":"Политики действуют в интересах всех граждан","value":"I"},{"text":"Большинство людей не могут реально влиять на политику","value":"E"}]},
    {"id":18,"text":"","type":"pair","options":[{"text":"Большинство людей не понимают, как их жизнь определяется случайностью","value":"E"},{"text":"Случайности вообще не существует","value":"I"}]},
    {"id":19,"text":"","type":"pair","options":[{"text":"Каждый должен признавать свои ошибки","value":"I"},{"text":"Обычно скрывать ошибки полезнее","value":"E"}]},
    {"id":20,"text":"","type":"pair","options":[{"text":"Трудно узнать, любят ли тебя","value":"E"},{"text":"Число друзей зависит от того, насколько привлекателен человек","value":"I"}]},
    {"id":21,"text":"","type":"pair","options":[{"text":"Жизнь в большинстве случаев определяется внешними событиями","value":"E"},{"text":"Решения, которые принимаю я — главная причина моей жизни","value":"I"}]},
    {"id":22,"text":"","type":"pair","options":[{"text":"Большинству людей трудно перебороть окружение","value":"E"},{"text":"Если захотеть, можно преодолеть любые барьеры","value":"I"}]},
    {"id":23,"text":"","type":"pair","options":[{"text":"Мир полон несправедливости и ничего не поделаешь","value":"E"},{"text":"Чаще всего несправедливость — результат нашего равнодушия","value":"I"}]},
    {"id":24,"text":"","type":"pair","options":[{"text":"Хороший руководитель ожидает, что его подчинённые решат, что делать","value":"E"},{"text":"Хороший руководитель сам определяет, что делать","value":"I"}]},
    {"id":25,"text":"","type":"pair","options":[{"text":"Одинокие люди виноваты в этом сами","value":"I"},{"text":"Одиночество — результат обстоятельств, с которыми трудно бороться","value":"E"}]},
    {"id":26,"text":"","type":"pair","options":[{"text":"Проигрыш в игре объясняется неудачей","value":"E"},{"text":"Проигрыш — результат слабой стратегии","value":"I"}]},
    {"id":27,"text":"","type":"pair","options":[{"text":"Мне кажется, что достаточно хотеть и можно всё сделать","value":"I"},{"text":"Жизнь трудна, и добиться успеха нелегко","value":"E"}]},
    {"id":28,"text":"","type":"pair","options":[{"text":"Иногда я не понимаю, чего хотят от меня учителя","value":"E"},{"text":"Когда стараюсь — мне понятно","value":"I"}]},
    {"id":29,"text":"","type":"pair","options":[{"text":"Я оказался жертвой ситуации","value":"E"},{"text":"Когда мне плохо — это последствия моих решений","value":"I"}]}
  ]'::jsonb,
  '{"formula":"rotter","external_value":"E","internal_value":"I","max_external":23}'::jsonb,
  '{
    "internal":{"range":[0,10],"label":"Интернальный локус контроля","description":"Вы убеждены, что сами управляете своей жизнью. Берёте ответственность за события."},
    "mixed":{"range":[11,16],"label":"Смешанный локус контроля","description":"Вы сочетаете принятие ответственности с признанием роли обстоятельств."},
    "external":{"range":[17,23],"label":"Экстернальный локус контроля","description":"Вы считаете, что жизнью управляют внешние силы. Склонны к фатализму."}
  }'::jsonb
);

-- ============================================================
-- TEST 8: Taylor Manifest Anxiety Scale (50 yes/no)
-- ============================================================
INSERT INTO public.tests (slug, title, description, category, estimated_minutes, questions, scoring, result_types)
VALUES (
  'taylor',
  'Шкала тревоги Тейлора',
  'Методика Дж. Тейлора измеряет уровень явной тревожности как устойчивой личностной характеристики.',
  'emotion',
  20,
  '[
    {"id":1,"text":"Обычно я спокоен и вывести меня из себя не так-то просто","key":"no","type":"yesno"},
    {"id":2,"text":"Мои нервы расстроены не больше, чем у других людей","key":"no","type":"yesno"},
    {"id":3,"text":"У меня редко бывают запоры","key":"no","type":"yesno"},
    {"id":4,"text":"У меня редко бывают головные боли","key":"no","type":"yesno"},
    {"id":5,"text":"Я редко устаю","key":"no","type":"yesno"},
    {"id":6,"text":"Я почти всегда чувствую себя вполне счастливым","key":"no","type":"yesno"},
    {"id":7,"text":"Я уверен в себе","key":"no","type":"yesno"},
    {"id":8,"text":"Я практически никогда не краснею","key":"no","type":"yesno"},
    {"id":9,"text":"По сравнению со своими друзьями я считаю себя вполне смелым","key":"no","type":"yesno"},
    {"id":10,"text":"Я краснею не чаще, чем обычно","key":"no","type":"yesno"},
    {"id":11,"text":"У меня редко бывают боли в сердце или сердцебиение","key":"no","type":"yesno"},
    {"id":12,"text":"Обычно мои руки достаточно тёплые","key":"no","type":"yesno"},
    {"id":13,"text":"Я застенчив не больше, чем другие","key":"no","type":"yesno"},
    {"id":14,"text":"Мне не хватает уверенности в себе","key":"yes","type":"yesno"},
    {"id":15,"text":"Порой мне кажется, что я ни на что не годен","key":"yes","type":"yesno"},
    {"id":16,"text":"У меня бывают периоды, когда я не могу усидеть на месте","key":"yes","type":"yesno"},
    {"id":17,"text":"Мой желудок сильно беспокоит меня","key":"yes","type":"yesno"},
    {"id":18,"text":"У меня не хватает духу вынести все предстоящие трудности","key":"yes","type":"yesno"},
    {"id":19,"text":"Я хотел бы быть таким же счастливым, как другие","key":"yes","type":"yesno"},
    {"id":20,"text":"Мне кажется порой, что передо мной нагромождены трудности, которые мне не преодолеть","key":"yes","type":"yesno"},
    {"id":21,"text":"Мне нередко снятся кошмарные сны","key":"yes","type":"yesno"},
    {"id":22,"text":"Я замечаю, что мои руки начинают дрожать, когда я пытаюсь что-нибудь сделать","key":"yes","type":"yesno"},
    {"id":23,"text":"У меня чрезвычайно беспокойный и прерывистый сон","key":"yes","type":"yesno"},
    {"id":24,"text":"Меня весьма тревожат возможные неудачи","key":"yes","type":"yesno"},
    {"id":25,"text":"Мне приходилось испытывать страх в тех случаях, когда точно знал, что мне ничего не угрожает","key":"yes","type":"yesno"},
    {"id":26,"text":"Мне трудно сосредоточиться на работе","key":"yes","type":"yesno"},
    {"id":27,"text":"Я работаю с большим напряжением","key":"yes","type":"yesno"},
    {"id":28,"text":"Я легко привожу в замешательство","key":"yes","type":"yesno"},
    {"id":29,"text":"Почти всё время я испытываю тревогу из-за кого-нибудь или чего-нибудь","key":"yes","type":"yesno"},
    {"id":30,"text":"Я склонен принимать всё слишком серьёзно","key":"yes","type":"yesno"},
    {"id":31,"text":"Я часто плачу","key":"yes","type":"yesno"},
    {"id":32,"text":"Меня нередко мучают приступы рвоты и тошноты","key":"yes","type":"yesno"},
    {"id":33,"text":"Раз в месяц или чаще у меня бывает расстройство желудка","key":"yes","type":"yesno"},
    {"id":34,"text":"Я часто боюсь, что вот-вот покраснею","key":"yes","type":"yesno"},
    {"id":35,"text":"Мне очень трудно сосредоточиться на чём-либо","key":"yes","type":"yesno"},
    {"id":36,"text":"Моё финансовое положение весьма беспокоит меня","key":"yes","type":"yesno"},
    {"id":37,"text":"Нередко я думаю о таких вещах, о которых ни с кем не хотелось бы говорить","key":"yes","type":"yesno"},
    {"id":38,"text":"У меня бывали периоды, когда тревога лишала меня сна","key":"yes","type":"yesno"},
    {"id":39,"text":"Временами, когда я нахожусь в замешательстве, у меня появляется сильная потливость","key":"yes","type":"yesno"},
    {"id":40,"text":"Даже в холодные дни я легко вспотею","key":"yes","type":"yesno"},
    {"id":41,"text":"Временами я становлюсь таким возбуждённым, что мне трудно заснуть","key":"yes","type":"yesno"},
    {"id":42,"text":"Я человек легко возбудимый","key":"yes","type":"yesno"},
    {"id":43,"text":"Временами я чувствую себя совершенно бесполезным","key":"yes","type":"yesno"},
    {"id":44,"text":"Порой мне кажется, что нервная система у меня расшатана и я вот-вот выйду из строя","key":"yes","type":"yesno"},
    {"id":45,"text":"Я часто ловлю себя на том, что меня что-то тревожит","key":"yes","type":"yesno"},
    {"id":46,"text":"Я часто расстраиваюсь из-за пустяков","key":"yes","type":"yesno"},
    {"id":47,"text":"Я почти никогда не замечаю у себя учащённого сердцебиения","key":"no","type":"yesno"},
    {"id":48,"text":"Я нахожу нужным уступить в споре","key":"no","type":"yesno"},
    {"id":49,"text":"Я не слишком застенчив","key":"no","type":"yesno"},
    {"id":50,"text":"Когда другие говорят, что меня воспринимают серьёзно, мне это не кажется смешным","key":"no","type":"yesno"}
  ]'::jsonb,
  '{"formula":"taylor","anxiety_key":"yes","no_anxiety_key":"no"}'::jsonb,
  '{
    "very_low":{"range":[0,5],"label":"Очень низкая тревожность","description":"Возможна недостаточная мотивация и осторожность."},
    "low":{"range":[6,10],"label":"Низкая тревожность","description":"Спокойное, уверенное состояние."},
    "medium":{"range":[11,25],"label":"Средняя тревожность","description":"Нормальный уровень. Позволяет эффективно справляться с задачами."},
    "high":{"range":[26,40],"label":"Высокая тревожность","description":"Выраженная тревожность. Рекомендуется работа над эмоциональной регуляцией."},
    "very_high":{"range":[41,50],"label":"Очень высокая тревожность","description":"Сильная тревожность. Рекомендуется консультация специалиста."}
  }'::jsonb
);

