-- TEST 9: Strelau Temperament Diagnosis (62 questions)
-- ============================================================
INSERT INTO public.tests (slug, title, description, category, estimated_minutes, questions, scoring, result_types)
VALUES (
  'strelau',
  'Диагностика темперамента Стреляу',
  'Методика Я. Стреляу измеряет три свойства нервной системы: силу возбуждения (SE), силу торможения (SI) и подвижность (SM).',
  'temperament',
  25,
  '[
    {"id":1,"text":"Легко ли вы обычно втягиваетесь в работу?","scale":"SE","key":"yes","type":"yesno"},
    {"id":2,"text":"Можете ли вы воздержаться от того или иного действия до тех пор, пока не получите распоряжения начать его?","scale":"SI","key":"yes","type":"yesno"},
    {"id":3,"text":"Дав себе слово что-нибудь не делать, легко ли вы держите своё обещание?","scale":"SI","key":"yes","type":"yesno"},
    {"id":4,"text":"Устаёте ли вы при работе, требующей постоянных изменений?","scale":"SM","key":"no","type":"yesno"},
    {"id":5,"text":"Засыпаете ли вы с одинаковой лёгкостью, ложась в постель в разное время суток?","scale":"SM","key":"yes","type":"yesno"},
    {"id":6,"text":"Трудно ли вам удерживаться от выполнения намеченного дела, если обстоятельства этому мешают?","scale":"SE","key":"yes","type":"yesno"},
    {"id":7,"text":"Умеете ли вы не торопиться?","scale":"SI","key":"yes","type":"yesno"},
    {"id":8,"text":"Нравится ли вам учиться новому, даже если это связано со значительными трудностями?","scale":"SE","key":"yes","type":"yesno"},
    {"id":9,"text":"Легко ли вы переключаетесь с одного вида деятельности на другой?","scale":"SM","key":"yes","type":"yesno"},
    {"id":10,"text":"Работаете ли вы с одинаковой активностью как в дневные, так и в утренние часы?","scale":"SM","key":"yes","type":"yesno"},
    {"id":11,"text":"Быстро ли вы осваиваетесь в незнакомом месте?","scale":"SM","key":"yes","type":"yesno"},
    {"id":12,"text":"Быстро ли вы забываете о неприятностях, которые пережили?","scale":"SE","key":"yes","type":"yesno"},
    {"id":13,"text":"Быстро ли вы привыкаете к новым людям?","scale":"SM","key":"yes","type":"yesno"},
    {"id":14,"text":"Когда вы слышите неприятное известие, можете ли вы продолжать работу?","scale":"SE","key":"yes","type":"yesno"},
    {"id":15,"text":"Легко ли вы переключаетесь с одной мысли на другую?","scale":"SM","key":"yes","type":"yesno"},
    {"id":16,"text":"Если вам мешают шум или разговоры, вы можете удержаться от выражения своего раздражения?","scale":"SI","key":"yes","type":"yesno"},
    {"id":17,"text":"Можете ли вы быстро принимать ответственные решения?","scale":"SE","key":"yes","type":"yesno"},
    {"id":18,"text":"Трудно ли вам привыкнуть к новым условиям работы?","scale":"SM","key":"no","type":"yesno"},
    {"id":19,"text":"Следуете ли вы распорядку дня, чтобы со всем успевать?","scale":"SI","key":"yes","type":"yesno"},
    {"id":20,"text":"Трудно ли вам прервать начатое дело?","scale":"SE","key":"no","type":"yesno"},
    {"id":21,"text":"Легко ли вам выполнять монотонную работу длительное время?","scale":"SE","key":"yes","type":"yesno"},
    {"id":22,"text":"Умеете ли вы в нужное время засыпать?","scale":"SI","key":"yes","type":"yesno"},
    {"id":23,"text":"Трудно ли вам устоять перед соблазном потратить деньги?","scale":"SI","key":"no","type":"yesno"},
    {"id":24,"text":"Легко ли вам приступить к делу, которое надо сделать в определённое время?","scale":"SM","key":"yes","type":"yesno"},
    {"id":25,"text":"Бывает ли, что вы чувствуете необходимость отдыхать после небольших нагрузок?","scale":"SE","key":"no","type":"yesno"},
    {"id":26,"text":"Трудно ли вам долго ждать чего-нибудь?","scale":"SI","key":"no","type":"yesno"},
    {"id":27,"text":"Переживаете ли вы неприятные события длительное время?","scale":"SE","key":"no","type":"yesno"},
    {"id":28,"text":"Работаете ли вы так же хорошо в неудобных условиях, как и в удобных?","scale":"SE","key":"yes","type":"yesno"},
    {"id":29,"text":"Трудно ли вам долго заниматься монотонной работой?","scale":"SE","key":"no","type":"yesno"},
    {"id":30,"text":"Легко ли вы переключаетесь при изменении условий труда?","scale":"SM","key":"yes","type":"yesno"},
    {"id":31,"text":"Без труда ли вы включаетесь в разговор?","scale":"SM","key":"yes","type":"yesno"},
    {"id":32,"text":"Склонны ли вы откладывать неприятные дела?","scale":"SI","key":"no","type":"yesno"},
    {"id":33,"text":"Можете ли вы долго работать без ошибок?","scale":"SE","key":"yes","type":"yesno"},
    {"id":34,"text":"Легко ли вам устанавливать контакты с новыми людьми?","scale":"SM","key":"yes","type":"yesno"},
    {"id":35,"text":"Можете ли вы, не торопясь, принять решение?","scale":"SI","key":"yes","type":"yesno"},
    {"id":36,"text":"Меняется ли у вас настроение без видимых причин?","scale":"SE","key":"no","type":"yesno"},
    {"id":37,"text":"Просыпаетесь ли вы легко по утрам?","scale":"SM","key":"yes","type":"yesno"},
    {"id":38,"text":"Трудно ли вам подчиняться правилам, если хочется их нарушить?","scale":"SI","key":"no","type":"yesno"},
    {"id":39,"text":"Можете ли вы спокойно реагировать на несправедливую критику?","scale":"SI","key":"yes","type":"yesno"},
    {"id":40,"text":"Трудно ли вам привыкнуть к новому режиму дня?","scale":"SM","key":"no","type":"yesno"},
    {"id":41,"text":"Беспокоят ли вас предстоящие события?","scale":"SE","key":"no","type":"yesno"},
    {"id":42,"text":"Легко ли вам запоминать новые имена?","scale":"SM","key":"yes","type":"yesno"},
    {"id":43,"text":"Быстро ли вы устаёте при умственной работе?","scale":"SE","key":"no","type":"yesno"},
    {"id":44,"text":"Часто ли вы бросаете начатое дело, не доведя до конца?","scale":"SI","key":"no","type":"yesno"},
    {"id":45,"text":"Предпочитаете ли вы работать в разнообразных условиях?","scale":"SM","key":"yes","type":"yesno"},
    {"id":46,"text":"Длительно ли вы переживаете обиду?","scale":"SE","key":"no","type":"yesno"},
    {"id":47,"text":"Можете ли вы не обращать внимания на посторонние раздражители?","scale":"SE","key":"yes","type":"yesno"},
    {"id":48,"text":"Способны ли вы сохранять спокойствие в трудных ситуациях?","scale":"SI","key":"yes","type":"yesno"},
    {"id":49,"text":"Хорошо ли вы ориентируетесь в незнакомой местности?","scale":"SM","key":"yes","type":"yesno"},
    {"id":50,"text":"Быстро ли вы находите выход из трудной ситуации?","scale":"SM","key":"yes","type":"yesno"},
    {"id":51,"text":"Легко ли вам сдержать смех в несоответствующей обстановке?","scale":"SI","key":"yes","type":"yesno"},
    {"id":52,"text":"Работаете ли вы интенсивно долгое время?","scale":"SE","key":"yes","type":"yesno"},
    {"id":53,"text":"Быстро ли вы теряетесь в незнакомой обстановке?","scale":"SM","key":"no","type":"yesno"},
    {"id":54,"text":"Легко ли вы запоминаете новый маршрут?","scale":"SM","key":"yes","type":"yesno"},
    {"id":55,"text":"Бываете ли вы вспыльчивы?","scale":"SI","key":"no","type":"yesno"},
    {"id":56,"text":"Чувствуете ли вы себя хорошо после длительной работы?","scale":"SE","key":"yes","type":"yesno"},
    {"id":57,"text":"Легко ли вы усваиваете новые методы работы?","scale":"SM","key":"yes","type":"yesno"},
    {"id":58,"text":"Начинаете ли вы заранее готовиться к важным делам?","scale":"SI","key":"yes","type":"yesno"},
    {"id":59,"text":"Трудно ли вам отказаться от привычного образа жизни?","scale":"SM","key":"no","type":"yesno"},
    {"id":60,"text":"Трудно ли вам сохранять хладнокровие в напряжённой обстановке?","scale":"SE","key":"no","type":"yesno"},
    {"id":61,"text":"Легко ли вам ориентироваться в большом городе?","scale":"SM","key":"yes","type":"yesno"},
    {"id":62,"text":"Трудно ли вам воздержаться от высказывания своего мнения?","scale":"SI","key":"no","type":"yesno"}
  ]'::jsonb,
  '{"formula":"strelau","scales":["SE","SI","SM"]}'::jsonb,
  '{
    "SE":{"name":"Сила возбуждения","low":"Слабый тип","high":"Сильный тип — высокая работоспособность"},
    "SI":{"name":"Сила торможения","low":"Неуравновешенный тип","high":"Уравновешенный тип — высокий самоконтроль"},
    "SM":{"name":"Подвижность","low":"Инертный тип","high":"Подвижный тип — легкая адаптация"}
  }'::jsonb
);

-- ============================================================
-- TEST 10: Belbin Team Roles (70 questions, 7 sections × 10 questions)
-- ============================================================
INSERT INTO public.tests (slug, title, description, category, estimated_minutes, questions, scoring, result_types)
VALUES (
  'belbin',
  'Тест Белбина (командные роли)',
  'Тест Р. М. Белбина определяет предпочтительные роли человека в команде. Распределите 10 баллов между вариантами ответов в каждом разделе.',
  'personality',
  30,
  '[
    {"id":1,"section":1,"section_title":"Что, по-моему, я привношу в команду","type":"distribute10","options":[
      {"letter":"a","text":"Мне кажется, что я хорошо умею замечать новые возможности и извлекать из них пользу","role":"RI"},
      {"letter":"b","text":"Я могу хорошо работать с самыми разными людьми","role":"TW"},
      {"letter":"c","text":"Выдвижение идей является одним из моих природных достоинств","role":"PL"},
      {"letter":"d","text":"Моя способность состоит в том, чтобы замечать людей с потенциалом и обращаться к ним","role":"CO"},
      {"letter":"e","text":"Моя способность доводить до конца всё начатое связана с моим личным успехом","role":"CF"},
      {"letter":"f","text":"Я готов встретить временную непопулярность, если в итоге это приводит к хорошим результатам","role":"SH"},
      {"letter":"g","text":"Я обычно чувствую, что реалистично и что осуществимо","role":"IMP"},
      {"letter":"h","text":"Я могу предложить разумные доводы в пользу альтернативных вариантов действий без предвзятости","role":"ME"}
    ]},
    {"id":2,"section":2,"section_title":"Мои недостатки в командной работе","type":"distribute10","options":[
      {"letter":"a","text":"Я нервничаю на совещаниях, если не разработана повестка и нет контроля за её соблюдением","role":"IMP"},
      {"letter":"b","text":"Я склонен быть слишком великодушен по отношению к тем, кто имеет ценную точку зрения","role":"ME"},
      {"letter":"c","text":"Я имею склонность слишком много говорить, когда команда приходит к новым идеям","role":"RI"},
      {"letter":"d","text":"Мой объективный взгляд мешает мне легко присоединяться к коллегам","role":"SH"},
      {"letter":"e","text":"Меня иногда видят как самонадеянного и авторитарного, когда что-то необходимо сделать","role":"CO"},
      {"letter":"f","text":"Мне трудно возглавить что-то из-за чрезмерного беспокойства об атмосфере в группе","role":"TW"},
      {"letter":"g","text":"Я склонен так увлекаться идеями, что не чувствую пульса собрания","role":"PL"},
      {"letter":"h","text":"Мои коллеги считают меня слишком беспокоящимся о деталях и возможных ошибках","role":"CF"}
    ]},
    {"id":3,"section":3,"section_title":"Когда я занят проектом вместе с другими людьми","type":"distribute10","options":[
      {"letter":"a","text":"Я имею способность влиять на людей без давления на них","role":"CO"},
      {"letter":"b","text":"Мои природные наблюдательность и осторожность предотвращают ошибки","role":"CF"},
      {"letter":"c","text":"Я готов настаивать на каком-то действии, чтобы убедиться, что встреча не тратит время и теряет цель из виду","role":"SH"},
      {"letter":"d","text":"Я могу предложить оригинальный вклад","role":"PL"},
      {"letter":"e","text":"Я всегда готов поддержать хорошее предложение в общих интересах команды","role":"TW"},
      {"letter":"f","text":"Я охотно разыскиваю новейшее в идеях, разработках и результатах","role":"RI"},
      {"letter":"g","text":"Я верю, что моя способность суждения помогает принять правильное решение","role":"ME"},
      {"letter":"h","text":"Я могу организовать реализацию согласованных планов","role":"IMP"}
    ]},
    {"id":4,"section":4,"section_title":"Мой подход к командной работе связан с тем, что","type":"distribute10","options":[
      {"letter":"a","text":"Я тихо интересуюсь тем, чтобы лучше узнать своих коллег","role":"TW"},
      {"letter":"b","text":"Я не боюсь оспорить точку зрения других или придерживаться меньшинства","role":"SH"},
      {"letter":"c","text":"Обычно я нахожу линию аргументации, чтобы опровергнуть несостоятельные предложения","role":"ME"},
      {"letter":"d","text":"Я думаю, что у меня есть способность воплощать планы в практику","role":"IMP"},
      {"letter":"e","text":"У меня есть склонность избегать очевидного и находить неожиданное","role":"PL"},
      {"letter":"f","text":"Я привношу совершенство в любую командную роль, которую я осуществляю","role":"CF"},
      {"letter":"g","text":"Я готов использовать контакты вне самой команды","role":"RI"},
      {"letter":"h","text":"Хотя меня интересуют все взгляды, я не испытываю сомнений при необходимости принять решение","role":"CO"}
    ]},
    {"id":5,"section":5,"section_title":"Я получаю удовольствие от работы, потому что","type":"distribute10","options":[
      {"letter":"a","text":"Мне нравится анализировать ситуации и взвешивать возможные варианты","role":"ME"},
      {"letter":"b","text":"Мне нравится находить практические решения проблем","role":"IMP"},
      {"letter":"c","text":"Мне нравится чувствовать, что я создаю хорошие рабочие отношения","role":"TW"},
      {"letter":"d","text":"Я могу оказать сильное влияние на принятие решений","role":"SH"},
      {"letter":"e","text":"Я встречаю людей, которые могут предложить что-то новое","role":"RI"},
      {"letter":"f","text":"Мне удаётся заставить людей согласиться с необходимым курсом действий","role":"CO"},
      {"letter":"g","text":"Я чувствую себя в своей стихии, когда могу отдать задаче всё своё внимание","role":"CF"},
      {"letter":"h","text":"Мне нравится находить сферу, которая расширяет мои творческие способности","role":"PL"}
    ]},
    {"id":6,"section":6,"section_title":"Если мне внезапно поручают трудное задание с незнакомыми людьми в сжатые сроки","type":"distribute10","options":[
      {"letter":"a","text":"Я бы проанализировал ситуацию и начал выработку плана действий","role":"ME"},
      {"letter":"b","text":"Я бы работал с тем, кто показал самый позитивный подход","role":"TW"},
      {"letter":"c","text":"Я бы нашёл способ уменьшить размер задачи, установив, чей вклад наибольший","role":"CO"},
      {"letter":"d","text":"Моё природное чувство срочности помогло бы в соблюдении сроков","role":"CF"},
      {"letter":"e","text":"Я думаю, что сохранил бы хладнокровие и способность мыслить объективно","role":"SH"},
      {"letter":"f","text":"Несмотря на давление, я бы держался своих целей","role":"IMP"},
      {"letter":"g","text":"Я бы взял инициативу, если бы чувствовал, что группа не прогрессирует","role":"PL"},
      {"letter":"h","text":"Я бы начал поиск контактов, которые могут помочь","role":"RI"}
    ]},
    {"id":7,"section":7,"section_title":"Что касается проблем в команде","type":"distribute10","options":[
      {"letter":"a","text":"Я склонен проявлять нетерпение, когда те, кто могли бы продвинуться, задерживают группу","role":"SH"},
      {"letter":"b","text":"Другие могут критиковать меня за то, что я слишком аналитичен и недостаточно интуитивен","role":"ME"},
      {"letter":"c","text":"Моё желание быть уверенным в том, что работа выполняется правильно, может сдерживать","role":"CF"},
      {"letter":"d","text":"Я стремлюсь немного надоедать, если только разговор не оживляется идеями","role":"PL"},
      {"letter":"e","text":"Трудно начать работу, если цели неясны","role":"IMP"},
      {"letter":"f","text":"Иногда мне не удаётся правильно объяснить сложные вопросы, которые я понимаю","role":"RI"},
      {"letter":"g","text":"Я понимаю, что могу требовать то, чего другие не могут предложить","role":"CO"},
      {"letter":"h","text":"Мне не хватает решительности, когда я встречаю реальное противодействие","role":"TW"}
    ]}
  ]'::jsonb,
